/// Without Jev's answers, the rule decides: the same command with the
/// same output, step after step, is stuck too. A window under the minimum
/// is raised to it, so the guard is never trigger-happy.
#[tokio::test]
async fn the_stuck_guard_falls_back_to_the_rule_and_has_a_minimum_window() {
    let script = Script::new(Vec::new());
    let limits = Limits {
        acceptance: false,
        stuck_steps: Some(1),
        ..Limits::unbounded()
    };
    let (_, outcome, ran, _) = go(&script, &limits).await;
    assert!(matches!(outcome.ending, Ending::Stuck(_)));
    assert_eq!(ran.len(), crate::run::MIN_STUCK_STEPS + 1);
    // Progress in between resets the count: Jev judges each step moving
    // forward, so the same command never ends the run.
    let mut replies: Vec<Result<NextAction, String>> = (0..20)
        .map(|_| Ok(act("again", &["true"], false)))
        .collect();
    replies.push(Ok(act("done", &[], true)));
    let script = Script::new(replies);
    let mut judge = jev(0.1);
    judge.progress = Some(0.7);
    judge.repeating = Some(0.9);
    let (_, outcome, _, _) = go_with(&script, &limits, &judge, None).await;
    assert_eq!(outcome.ending, Ending::Finished);
}

/// A continuation that breaks the rules is never shown: the stem's
/// generic end closes the sentence, and the bank is the `model`.
#[tokio::test]
async fn an_invalid_continuation_falls_back_to_the_generic_end() {
    let answers = routed("work.dispatch", "dispatch.stem", 0.9, "none");
    let frames = frames_routed(
        slow_door(Duration::from_millis(1_500)),
        Some(judge(Duration::ZERO, answers)),
        routed_turn("fix it", json!({})),
        personalized(" fix it. I already fixed it at https://example.com"),
        RouterSetting::Live,
    )
    .await;
    let result = &frames.last().unwrap().1;
    assert_eq!(result["text"], "Working on this.");
    assert_eq!(result["model"], "bank:chat-answers-v1");
}

#[test]
fn linux_paths_follow_xdg() {
    assert_eq!(
        unit_dir(Some(Path::new("/cfg")), Path::new("/home/kai")),
        PathBuf::from("/cfg/systemd/user")
    );
    assert_eq!(
        unit_dir(Some(Path::new("relative")), Path::new("/home/kai")),
        PathBuf::from("/home/kai/.config/systemd/user")
    );
    assert_eq!(
        openagents_desktop::control::socket_path_for(
            "linux",
            None,
            Some(Path::new("/run/user/1000"))
        ),
        Some(PathBuf::from("/run/user/1000/openagents/control.sock"))
    );
}

/// The read-only engine report for one computer.
///
/// `signed_in` says whether each provider's local login is present. The
/// report carries provider names, model ids, percents, and reset times. It
/// carries no credential, account identifier, or controller path. Its
/// accounts are Codex and Claude Code, then Grok Build when it is signed
/// in here ([`engine_report_with`] also shows it when only installed).
#[must_use]
pub fn engine_report(
    policy: Option<&Policy>,
    now: u64,
    signed_in: &dyn Fn(Provider) -> bool,
    usage: &usage::Book,
) -> EngineReport {
    engine_report_with(policy, now, signed_in, &|_| false, usage)
}

#[cfg(unix)]
#[test]
fn the_login_path_is_read_after_the_marker() {
    let text = format!("Welcome!\n{LOGIN_MARKER}/opt/homebrew/bin:/usr/bin\n");
    assert_eq!(
        login_path_from(&text),
        Some("/opt/homebrew/bin:/usr/bin".into())
    );
    assert_eq!(login_path_from("no marker"), None);
}

/// The engine's file name on this platform.
